<main class="pt-28 sm:pt-32">
    <section class="relative overflow-hidden bg-surface-container-low px-4 py-12 sm:px-6 sm:py-16 lg:px-8">
        <div class="absolute -right-32 -top-32 h-96 w-96 rounded-full bg-primary/10 blur-3xl"></div>
        <div class="relative mx-auto max-w-7xl">
            <div class="max-w-3xl">
                <span class="inline-flex rounded-full bg-primary/10 px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-primary"><span class="mr-2 h-2 w-2 rounded-full bg-secondary"></span>Federation advocacy &amp; social impact</span>
                <h1 class="mt-5 font-headline text-4xl font-extrabold leading-tight tracking-tight text-on-surface sm:text-5xl lg:text-6xl">There is a place for you in the <span class="relative inline-block text-primary-container">FLAME PH ecosystem.<span class="absolute bottom-0 left-0 h-1 w-full rounded-full bg-secondary"></span></span></h1>
                <p class="mt-5 max-w-2xl text-base leading-7 text-on-surface-variant sm:text-lg">Whether you are an industry executive, an experienced entrepreneur, a corporate donor, a regional leader, or an advocate for grassroots livelihood—lend your voice, resources, and mentorship to uplift Filipino MSMEs across 82 provinces. <strong class="text-primary">Bayanihan</strong> is our strongest national infrastructure.</p>
                <div class="mt-7 flex flex-col gap-3 sm:flex-row"><a class="inline-flex items-center justify-center rounded-full bg-secondary px-6 py-3 font-bold text-white shadow-lg hover:bg-secondary-container" href="#involvement-paths"><span class="mr-2">↓</span>Get Involved Today</a><a class="inline-flex items-center justify-center rounded-full bg-white px-6 py-3 font-bold text-primary shadow-sm hover:bg-surface-container" href="/membership#registration"><span class="mr-2 text-tertiary-container">★</span>Join FLAME PH Free →</a></div>
            </div>
            <div class="mt-10 grid grid-cols-2 gap-4 rounded-2xl bg-white p-5 shadow-md ring-1 ring-primary/5 sm:grid-cols-4 sm:gap-0">
                <div class="flex items-center gap-3 border-b pb-4 sm:border-b-0 sm:border-r sm:px-5 sm:pb-0"><span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><span class="material-symbols-outlined">groups</span></span><div><strong class="block text-xl text-primary sm:text-2xl">1,200+</strong><span class="text-xs text-on-surface-variant sm:text-sm">Active Mentors &amp; Advisors</span></div></div>
                <div class="flex items-center gap-3 border-b pb-4 sm:border-b-0 sm:border-r sm:px-5 sm:pb-0"><span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-amber-100 text-tertiary-container"><span class="material-symbols-outlined">payments</span></span><div><strong class="block text-xl text-primary sm:text-2xl">₱12.8M</strong><span class="text-xs text-on-surface-variant sm:text-sm">Livelihood Grants Matched</span></div></div>
                <div class="flex items-center gap-3 sm:border-r sm:px-5"><span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-red-100 text-secondary"><span class="material-symbols-outlined">location_on</span></span><div><strong class="block text-xl text-primary sm:text-2xl">180+</strong><span class="text-xs text-on-surface-variant sm:text-sm">Barangay Chapters</span></div></div>
                <div class="flex items-center gap-3 sm:px-5"><span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><span class="material-symbols-outlined">storefront</span></span><div><strong class="block text-xl text-primary sm:text-2xl">24,000+</strong><span class="text-xs text-on-surface-variant sm:text-sm">MSME Owners Mentored</span></div></div>
            </div>
        </div>
